  const history=[...(base.editorial_history||[]),{parent_package_id:base.id,parent_payload_hash:base.payload_hash,at,review_notes:body.review_notes.trim(),claim_fact_ids:body.claim_fact_ids,model_calls:0}].slice(-20);
  const payload={...prior,...content,project_highlights:projects,job_version:job.raw_hash,eligibility:job.assessment,facts,claim_fact_ids:body.claim_fact_ids,selection:{fact_ids:body.claim_fact_ids,requirement_quote:base.selection?.requirement_quote||'',drafts:{cover_letter:content.cover_letter,cold_email_subject:content.cold_email_subject,cold_email:content.cold_email,cv_summary:content.cv_summary_draft,fact_ids:body.claim_fact_ids},generation:'owner_editorial_revision'},resume_full:resume,full_cv_preserved:true,full_cv_source_hash:master.sha256,writing_profile_version:WRITING_PROFILE.version,generation:'Owner-edited application drafts',review_note:null,claim_review:'Owner revision saved with source references, complete numeric tokens and known scope-conflation checks. Review the final wording; nothing was approved or sent.',editorial_history:history,model_calls:0,limitations:['The complete master CV is preserved; its headline, summary and selected verbatim project highlights are tailored.','This is a new internal review version. Earlier versions are retained and their approvals do not apply.','Numbers and selected source references are checked; ownership and cross-employer phrasing still require your review.','No email or application was sent. Approval and any external action remain separate.']};
