async function apolloPeopleSearch(env,body){
  const domain=String(body.company_domain||'').trim().toLowerCase().replace(/^https?:\/\//,'').split('/')[0].replace(/^www\./,'');
  if(!/^(?=.{1,253}$)(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$/.test(domain))throw new Error('Enter the employer website domain, such as company.com');
  if(typeof body.job_id!=='string'||body.job_id.length>250)throw new Error('Select a current HUNT job first');
  const snapshot=await mergedSnapshot(env.BUCKET),job=snapshot.jobs.find(j=>j.id===body.job_id);if(!job||!job.open)throw new Error('The selected job is no longer open');
  const titles=['Recruiter','Talent Acquisition','Human Resources','People Operations','Chief People Officer','Founder','Co-Founder'];
  const response=await remoteJSON('https://api.apollo.io/api/v1/mixed_people/api_search',{timeout_ms:20000,method:'POST',headers:{'Content-Type':'application/json','x-api-key':env.APOLLO_API_KEY},body:JSON.stringify({person_titles:titles,q_organization_domains_list:[domain],include_similar_titles:true,page:1,per_page:10})});
  const contacts=(Array.isArray(response.people)?response.people:[]).slice(0,10).map(person=>{let linkedin=null;try{const u=new URL(person.linkedin_url);if(['http:','https:'].includes(u.protocol)&&u.hostname.toLowerCase().endsWith('linkedin.com')&&!u.username&&!u.password){u.protocol='https:';linkedin=u.href}}catch{}return {id:String(person.id||''),first_name:String(person.first_name||''),last_name_obfuscated:String(person.last_name_obfuscated||''),title:String(person.title||''),organization:String(person.organization?.name||''),linkedin_url:linkedin,has_email:person.has_email===true}});
  return {job_id:job.id,company:job.company,company_domain:domain,contacts,total_entries:Number(response.total_entries||contacts.length),source:'Apollo People API Search',credits_used:0,email_disclosure:'Apollo search returns LinkedIn/profile metadata and an email-availability indicator, not email addresses. Email enrichment is a separate potentially credit-consuming action.',message:contacts.length?'Select a LinkedIn profile for outreach; verify the person is connected to this exact vacancy. No email was revealed or message sent.':'Apollo returned no matching contacts for this domain and title set.'};
}

