      if(!user&&env.HUNT_PUBLIC_READ==='true'&&(!env.HUNT_BRIDGE_SECRET||!equal(req.headers.get('X-HUNT-Service-Authorization'),env.HUNT_BRIDGE_SECRET)))return reply({error:'Owner service authorization required. Authorized background clients must send the existing owner Site service token in X-HUNT-Service-Authorization as well as OAI-Sites-Authorization.'},401);
